public class GithubScmContentProviderTest extends GithubMockBase {}
/**************TEST SETUP BEGIN*************/
@BeforeClass
public static void enableJWT(){
    System.setProperty("BLUEOCEAN_FEATURE_JWT_AUTHENTICATION", "true");
}
/**************TEST SETUP END*************/
/**************TEST METHOD BEGIN*************/
@Test
public void saveContentToMbpMissingBranch() throws UnirestException, IOException{
        String credentialId = createGithubCredential(user);

        StaplerRequest2 staplerRequest = mockStapler();

        GitContent content = new GitContent.Builder().autoCreateBranch(true).base64Data("c2xlZXAgMTUKbm9kZSB7CiAgY2hlY2tvdXQgc2NtCiAgc2ggJ2xzIC1sJwp9\\nCnNsZWVwIDE1Cg==\\n")
                .branch("test2").message("another commit").owner("cloudbeers").path("Jankinsfile").repo("PR-demo").sha("e23b8ef5c2c4244889bf94db6c05cc08ea138aef").build();

        when(staplerRequest.bindJSON(Mockito.eq(GithubScmSaveFileRequest.class), Mockito.any(JSONObject.class))).thenReturn(new GithubScmSaveFileRequest(content));

        MultiBranchProject mbp = mockMbp(credentialId, user, GithubScm.DOMAIN_NAME);

        String request = "{\n" +
                "  \"content\" : {\n" +
                "    \"message\" : \"first commit\",\n" +
                "    \"path\" : \"Jenkinsfile\",\n" +
                "    \"branch\" : \"test2\",\n" +
                "    \"repo\" : \"PR-demo\",\n" +
                "    \"sha\" : \"e23b8ef5c2c4244889bf94db6c05cc08ea138aef\",\n" +
                "    \"base64Data\" : "+"\"c2xlZXAgMTUKbm9kZSB7CiAgY2hlY2tvdXQgc2NtCiAgc2ggJ2xzIC1sJwp9\\nCnNsZWVwIDE1Cg==\\n\""+
                "  }\n" +
                "}";

        when(staplerRequest.getReader()).thenReturn(new BufferedReader(new StringReader(request), request.length()));

        GithubFile file = (GithubFile) new GithubScmContentProvider().saveContent(staplerRequest, mbp);
        assertEquals("Jenkinsfile", file.getContent().getName());
        assertEquals("e23b8ef5c2c4244889bf94db6c05cc08ea138aef", file.getContent().getSha());
        assertEquals("PR-demo", file.getContent().getRepo());
        assertEquals("cloudbeers", file.getContent().getOwner());
    }
/**************TEST METHOD END*************/
/**************TEST HELPER METHOD BEGIN*************/
protected StaplerRequest2 mockStapler(){
        return mockStapler("github");
    }
private StaplerRequest2 mockStapler(String scmId){
        mockStatic(Stapler.class);
        StaplerRequest2 staplerRequest = mock(StaplerRequest2.class);
        when(Stapler.getCurrentRequest2()).thenReturn(staplerRequest);
        when(staplerRequest.getRequestURI()).thenReturn("http://localhost:8080/jenkins/blue/rest/");
        when(staplerRequest.getParameter("path")).thenReturn("Jenkinsfile");
        when(staplerRequest.getParameter("repo")).thenReturn("PR-demo");

        // GithubScmContentProvider determines SCM using apiUrl but with wiremock
        // apiUrl is localhost and not github so we use this parameter from test only to tell scm id
        when(staplerRequest.getParameter("scmId")).thenReturn(scmId);
        when(staplerRequest.getParameter("apiUrl")).thenReturn(githubApiUrl);
        return staplerRequest;
    }
protected String createGithubCredential(User user) throws UnirestException{
        Map r = new RequestBuilder(baseUrl).data(MapsHelper.of("accessToken", accessToken)).status(200).jwtToken(getJwtToken(j.jenkins, user.getId(), user.getId())).crumb(this.crumb).post("/organizations/" + getOrgName() + "/scm/github/validate/?apiUrl=" + githubApiUrl).build(Map.class);
        String credentialId = (String) r.get("credentialId");
        assertEquals(GithubScm.ID, credentialId);
        return credentialId;
    }
static String getOrgName(){
        return OrganizationFactory.getInstance().list().iterator().next().getName();
    }
protected MultiBranchProject mockMbp(String credentialId, User user, String credentialDomainName){
        MultiBranchProject mbp = mock(MultiBranchProject.class);
        when(mbp.getName()).thenReturn("PR-demo");
        when(mbp.getParent()).thenReturn(j.jenkins);
        GitHubSCMSource scmSource = mock(GitHubSCMSource.class);
        when(scmSource.getApiUri()).thenReturn(githubApiUrl);
        when(scmSource.getCredentialsId()).thenReturn(credentialId);
        when(scmSource.getRepoOwner()).thenReturn("cloudbeers");
        when(scmSource.getRepository()).thenReturn("PR-demo");
        when(mbp.getSCMSources()).thenReturn(Collections.singletonList(scmSource));
        BlueOceanCredentialsProvider.FolderPropertyImpl folderProperty = mock(BlueOceanCredentialsProvider.FolderPropertyImpl.class);
        DescribableList<AbstractFolderProperty<?>, AbstractFolderPropertyDescriptor> mbpProperties = new DescribableList<>(mbp);
        mbpProperties.add(new BlueOceanCredentialsProvider.FolderPropertyImpl(user.getId(), credentialId, BlueOceanCredentialsProvider.createDomain(githubApiUrl)));
        Domain domain = mock(Domain.class);
        when(domain.getName()).thenReturn(credentialDomainName);
        when(folderProperty.getDomain()).thenReturn(domain);
        when(mbp.getProperties()).thenReturn(mbpProperties);
        return mbp;
    }
public static String getJwtToken(Jenkins jenkins, String username, String password) throws UnirestException{
        GetRequest request = Unirest.get(jenkins.getRootUrl() + "jwt-auth/token/").header("Accept", "*/*").header("Accept-Encoding", "");
        if (username != null && password != null) {
            request.basicAuth(username, password);
        }
        HttpResponse<String> response = request.asString();
        String token = response.getHeaders().getFirst(X_BLUEOCEAN_JWT);
        Assert.assertNotNull(token);
        return token;
    }
