protected void createCredentialWithId(String jwt, String credentialId){
        createCredentialWithIdForOrg(jwt, credentialId, "jenkins");
    }
protected void createCredentialWithIdForOrg(String jwt, String credentialId, String orgName){
        request().jwtToken(jwt).crumb(crumb).data(MapsHelper.of("credentials", new MapsHelper.Builder().put("scope", "USER").put("id", credentialId).put("username", "username").put("password", "password").put("stapler-class", "com.cloudbees.plugins.credentials.impl.UsernamePasswordCredentialsImpl").put("$class", "com.cloudbees.plugins.credentials.impl.UsernamePasswordCredentialsImpl").build())).post("/organizations/" + orgName + "/credentials/user/").status(201).build(JSONObject.class);
    }
public RequestBuilder request(){
        return new RequestBuilder(baseUrl);
    }
public static String getJwtToken(Jenkins jenkins, String username, String password) throws UnirestException{
        GetRequest request = Unirest.get(jenkins.getRootUrl() + "jwt-auth/token/").header("Accept", "*/*").header("Accept-Encoding", "");
        if (username != null && password != null) {
            request.basicAuth(username, password);
        }
        HttpResponse<String> response = request.asString();
        String token = response.getHeaders().getFirst(X_BLUEOCEAN_JWT);
        Assert.assertNotNull(token);
        return token;
    }
